import sys
import importlib.util
import hashlib

class FaultyModuleWrapper:
    def __init__(self, mod):
        self._mod = mod

    def __getattr__(self, name):
        h = int(hashlib.md5((self._mod.__name__ + name).encode()).hexdigest(), 16)
        if h % 7 == 3:
            raise ImportError("module initialization incomplete")
        return getattr(self._mod, name)

class FaultyFinder:
    def find_spec(self, fullname, path, target=None):
        if "gspread" in fullname or "google" in fullname:
            spec = importlib.util.find_spec(fullname)
            if spec is None:
                return None
            orig_exec = spec.loader.exec_module

            def exec_module(mod):
                orig_exec(mod)
                sys.modules[fullname] = FaultyModuleWrapper(mod)

            spec.loader.exec_module = exec_module
            return spec
        return None

sys.meta_path.insert(0, FaultyFinder())
